import React, { useState } from 'react'
import {
  StyleSheet,
  Text,
  View,
  ViewStyle,
  Pressable,
  Alert,
  Image,
} from 'react-native'
import { COLOR } from '@/constants'
import Icon from './Icon'
import * as ImagePickerLib from 'expo-image-picker'

interface ImagePickerProps {
  label?: string
  value?: string
  onValueChange: (uri: string) => void
  placeholder?: string
  errorText?: string
  style?: ViewStyle | ViewStyle[]
  testID?: string
  disabled?: boolean
}

/**
 * ImagePicker: Componente para seleccionar imágenes desde cámara o galería
 */
const ImagePicker: React.FC<ImagePickerProps> = ({
  label,
  value,
  onValueChange,
  placeholder = 'Agregar foto',
  errorText,
  style,
  testID,
  disabled = false,
}) => {
  const [loading, setLoading] = useState(false)

  const requestPermissions = async (type: 'camera' | 'library') => {
    try {
      const permission =
        type === 'camera'
          ? await ImagePickerLib.requestCameraPermissionsAsync()
          : await ImagePickerLib.requestMediaLibraryPermissionsAsync()

      if (!permission.granted) {
        Alert.alert(
          'Permisos necesarios',
          `Necesitamos acceso a tu ${type === 'camera' ? 'cámara' : 'galería'} para continuar.`
        )
        return false
      }
      return true
    } catch (error) {
      console.error('Error requesting permissions:', error)
      return false
    }
  }

  const pickFromCamera = async () => {
    const hasPermission = await requestPermissions('camera')
    if (!hasPermission) return

    setLoading(true)
    try {
      const result = await ImagePickerLib.launchCameraAsync({
        mediaTypes: ImagePickerLib.MediaTypeOptions.Images,
        allowsEditing: true,
        aspect: [1, 1],
        quality: 0.8,
      })

      if (!result.canceled && result.assets[0]) {
        onValueChange(result.assets[0].uri)
      }
    } catch (error) {
      console.error('Error picking from camera:', error)
      Alert.alert('Error', 'No se pudo tomar la foto')
    } finally {
      setLoading(false)
    }
  }

  const pickFromLibrary = async () => {
    const hasPermission = await requestPermissions('library')
    if (!hasPermission) return

    setLoading(true)
    try {
      const result = await ImagePickerLib.launchImageLibraryAsync({
        mediaTypes: ImagePickerLib.MediaTypeOptions.Images,
        allowsEditing: true,
        aspect: [1, 1],
        quality: 0.8,
      })

      if (!result.canceled && result.assets[0]) {
        onValueChange(result.assets[0].uri)
      }
    } catch (error) {
      console.error('Error picking from library:', error)
      Alert.alert('Error', 'No se pudo seleccionar la imagen')
    } finally {
      setLoading(false)
    }
  }

  const showOptions = () => {
    Alert.alert(
      'Seleccionar foto',
      'Elige una opción',
      [
        {
