import { useState } from 'react'
import { ServicioPaseo } from '@/services/firebase'
import type { PaseoEvent } from '@/services/firebase/maquina-estados-paseo'
import { crearMaquinaPaseo } from '@/services/firebase/maquina-estados-paseo'
import { Alert } from 'react-native'
import { useTranslation } from 'react-i18next'
import { usePaseoActivo } from '@/hooks/paseos/usePaseoActivo'

/**
 * Hook para controlar un paseo desde la perspectiva del cuidador.
 * Reutiliza usePaseoActivo y agrega funcionalidad de cambio de estado.
 */
export const useControlPaseo = (paseoId: string) => {
  const { t } = useTranslation()
  const { paseo, loading, eventos, ruta, ubicacionActual } =
    usePaseoActivo(paseoId)
  const [procesando, setProcesando] = useState(false)

  // Cambiar estado del paseo usando la máquina de estados
  const cambiarEstado = async (evento: PaseoEvent) => {
    if (!paseo) return

    setProcesando(true)
    try {
      // Validar transición con la máquina
      const maquina = crearMaquinaPaseo(paseo)
      if (!maquina.puede(evento)) {
        Alert.alert(t('comun:error'), t('paseos:control.transicion_invalida'))
        setProcesando(false)
        return
      }

      // Ejecutar transición según el evento
      let resultado
      switch (evento) {
        case 'INICIAR_RUTA':
          resultado = await ServicioPaseo.iniciarRuta(paseo.id)
          break
        case 'INICIAR_PASEO':
          resultado = await ServicioPaseo.iniciarPaseo(paseo.id)
          break
        case 'FINALIZAR_PASEO':
          resultado = await ServicioPaseo.finalizarPaseo(paseo.id)
          break
        default:
          throw new Error('Evento no implementado')
      }

      if (!resultado.success) {
        Alert.alert(
          t('comun:error'),
          resultado.error || t('comun:error_desconocido')
        )
      }
    } catch (e: any) {
      Alert.alert(t('comun:error'), e.message || t('comun:error_desconocido'))
    } finally {
      setProcesando(false)
    }
  }

  // Calcular tiempo transcurrido
  const tiempoTranscurrido = paseo?.fecha_inicio_real
    ? Math.floor(
        (Date.now() - new Date(paseo.fecha_inicio_real).getTime()) / 1000
      )
    : 0

  return {
    paseo,
    loading,
    eventos,
    ruta,
    ubicacionActual,
    procesando,
    cambiarEstado,
    tiempoTranscurrido,
  }
}

import { useState, useCallback, useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import { useMascotas } from '@/hooks/useMascotas'
import { ServicioPaseo } from '@/services/firebase'
import { ServicioPerfilPublico, ServicioUbicaciones } from '@/services/firebase'
import { PaseoStatus } from '@/models/Paseo'
import { useAuth } from '@/context/AuthContext'
import type { Ubicacion } from '@/models/Ubicacion'

interface ConfirmarPaseoProps {
  mascotaIds: string[]
  direccionId: string | null
  cuidadorId: string | null
  fecha: Date | null
  hora: string | null
  duracion: number | null
  esCompartido: boolean
}

interface CuidadorInfo {
  id: string
  nombre: string
  imagen: string
  tarifa: number
}

export const useConfirmarPaseo = ({
  mascotaIds,
  direccionId,
  cuidadorId,
  fecha,
  hora,
  duracion,
  esCompartido,
}: ConfirmarPaseoProps) => {
  const { t } = useTranslation()
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [cuidador, setCuidador] = useState<CuidadorInfo | null>(null)
  const [direccion, setDireccion] = useState<Ubicacion | null>(null)
  const { user } = useAuth()
  const { mascotas: todasLasMascotas } = useMascotas()

  // Obtener datos completos de los ID
  const mascotas = todasLasMascotas.filter(p => mascotaIds.includes(p.id))

  // Cargar datos del cuidador y dirección
  useEffect(() => {
    const cargarDatos = async () => {
      setLoading(true)
      try {
        const promises: Promise<any>[] = []

        if (cuidadorId) {
          promises.push(ServicioPerfilPublico.obtenerPorId(cuidadorId))
        } else {
          promises.push(Promise.resolve(null))
        }

        if (direccionId) {
          promises.push(ServicioUbicaciones.obtenerPorId(direccionId))
        } else {
          promises.push(Promise.resolve(null))
        }

        const [resCuidador, resUbicacion] = await Promise.all(promises)

        if (resCuidador?.success && resCuidador.data) {
          const perfil = resCuidador.data
          setCuidador({
            id: perfil.id,
            nombre: perfil.nombre,
            imagen: perfil.foto || 'https://via.placeholder.com/60',
            tarifa: perfil.tarifa_por_hora || 15000,
          })
        }

        if (resUbicacion?.success && resUbicacion.data) {
          setDireccion(resUbicacion.data)
        }
      } catch (err) {
        console.error('Error cargando datos de confirmación:', err)
      } finally {
        setLoading(false)
      }
    }

    cargarDatos()
  }, [cuidadorId, direccionId])

  // Cálculo simple de costos
  const tarifaBase = cuidador?.tarifa || 15000
  const tarifaMascotaAdicional = 5000 // Tarifa adicional por mascota extra
  const numMascotas = mascotas.length
  const duracionMinutos = duracion || 60
  const factorDuracion = duracionMinutos / 60

  // Si es más de una, sumamos extra por cada adicional
  const totalBase =
    numMascotas > 0
      ? tarifaBase + (numMascotas - 1) * tarifaMascotaAdicional
      : 0

  const total = totalBase * factorDuracion

  const confirmarReserva = useCallback(async () => {
    if (!fecha || !hora) {
      setError(t('paseos:flujo.errores.fecha_hora_requerida'))
      return false
    }

    if (!direccionId) {
      setError(t('paseos:flujo.errores.ubicacion_requerida'))
      return false
    }

    setLoading(true)
    setError(null)

    try {
      // Combinar fecha y hora
      const fechaInicio = new Date(fecha)
      const [hours, minutes] = hora.split(':').map(Number)
      fechaInicio.setHours(hours, minutes, 0, 0)

      const result = await ServicioPaseo.crearConMascotas(
        {
          tipo_paseo: 'solicitado',
          estado: PaseoStatus.PENDIENTE,
          fecha_hora_inicio: fechaInicio,
          duracion_estimada: duracion || 60,
          precio: total,
          ubicacion_inicio: direccion || undefined,
          id_cuidador: cuidadorId || undefined,
          cuidador_nombre_visual: cuidador?.nombre,
          cuidador_foto_visual: cuidador?.imagen,
          modalidad: esCompartido ? 'compartido' : 'privado',
          cupo_maximo_mascotas: esCompartido ? 10 : mascotas.length,
          tutor_ids: user?.uid ? [user.uid] : [],
        },
        mascotaIds,
        direccion || undefined
      )

      if (!result.success) {
        throw new Error(result.error)
      }

      return true
    } catch (e: any) {
      console.error('Error creando paseo:', e)
      setError(e.message || 'Error desconocido')
      return false
    } finally {
      setLoading(false)
    }
  }, [
    fecha,
    hora,
    duracion,
    total,
    cuidadorId,
    mascotaIds,
    mascotas.length,
    esCompartido,
    cuidador,
    user,
    direccion,
    direccionId,
    t,
  ])

  return {
    mascotas,
    cuidador,
    direccion,
    total,
    loading,
    error,
    confirmarReserva,
  }
}

import { useState, useCallback, useMemo } from 'react'
import { useAuth } from '@/context/AuthContext'
import { ServicioUsuario, ServicioUbicaciones } from '@/services/firebase'
import { UbicacionRef } from '@/models/Ubicacion'

export function useDirecciones() {
  const { user, profile, recargarPerfil } = useAuth()
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Las ubicaciones vienen del perfil de usuario (Firestore), no del objeto AuthUser (Firebase Auth)
  const direcciones = useMemo(
    () => profile?.ubicaciones || [],
    [profile?.ubicaciones]
  )

  const principal = useMemo(() => {
    return direcciones.find(d => d.es_principal)
  }, [direcciones])

  const agregar = useCallback(
    async (datos: any, alias: string = 'Casa'): Promise<string> => {
      if (!user?.uid) throw new Error('NO_AUTENTICADO')
      setLoading(true)
      setError(null)

      try {
        // 1. Crear documento real en /direcciones
        const ubicacionNueva = {
          ...datos, // debe incluir coordenadas, direccion_formateada, etc.
          estado: 'pendiente',
        }
        const resUbic = await ServicioUbicaciones.crear(ubicacionNueva)
        if (!resUbic.success || !resUbic.data)
          throw new Error('ERROR_CREAR_UBICACION')

        const nuevaId = resUbic.data.id

        // 2. Ligar al usuario con snapshot de coordenadas
        const resUser = await ServicioUsuario.agregarUbicacion(
          user.uid,
          nuevaId,
          alias,
          datos.coordenadas // Snapshot crucial para el mapa
        )

        if (!resUser.success) throw new Error(String(resUser.error))

        await recargarPerfil()
        return nuevaId // Retornar ID para seleccionarlo en UI
      } catch (e: any) {
        setError(String(e))
        throw e
      } finally {
        setLoading(false)
      }
    },
    [user?.uid, recargarPerfil]
  )

  const fijarPrincipal = useCallback(
    async (ubicacionId: string): Promise<void> => {
      if (!user?.uid) throw new Error('NO_AUTENTICADO')
      setLoading(true)
      setError(null)
      const res = await ServicioUsuario.fijarUbicacionPrincipal(
        user.uid,
        ubicacionId
      )
      setLoading(false)
      if (res.success) {
        await recargarPerfil()
      } else {
        setError(String(res.error))
        throw new Error(String(res.error))
      }
    },
    [user?.uid, recargarPerfil]
  )

  const eliminar = useCallback(
    async (ubicacionId: string): Promise<void> => {
      if (!user?.uid) throw new Error('NO_AUTENTICADO')
      setLoading(true)
      setError(null)
      const res = await ServicioUsuario.eliminarUbicacion(user.uid, ubicacionId)
      setLoading(false)
      if (res.success) {
        await recargarPerfil()
      } else {
        setError(String(res.error))
        throw new Error(String(res.error))
      }
    },
    [user?.uid, recargarPerfil]
  )

  return {
    direcciones,
    principal,
    loading,
    error,
    agregar,
    fijarPrincipal,
    eliminar,
    // Helpers visuales
    tieneDirecciones: direcciones.length > 0,
    usuarioId: user?.uid,
  }
}

import { BaseModel } from './BaseModel'
import type { UbicacionSnapshot } from '@/models/Ubicacion'

/**
 * Tipos de paseo disponibles.
 * 'solicitado' para paseos a demanda, 'programado' para paseos con horario fijo.
 */
export type TipoPaseo = 'solicitado' | 'programado'

/**
 * Estados posibles de un paseo.
 * Controla el flujo desde solicitud hasta conclusión o cancelación.
 */
export enum PaseoStatus {
  PENDIENTE = 'PENDIENTE',
  CONFIRMADO = 'CONFIRMADO',
  EN_RUTA = 'EN_RUTA',
  EN_PROGRESO = 'EN_PROGRESO',
  FINALIZADO = 'FINALIZADO',
  COMPLETADO = 'COMPLETADO',
  CANCELADO = 'CANCELADO',
  ERROR = 'ERROR',
}

/**
 * Modalidad del paseo que define si acepta mascotas de otros tutores.
 * 'privado' = Solo las mascotas del tutor que creó el paseo
 * 'compartido' = Acepta que otros tutores unan sus mascotas (paseo grupal)
 */
export type ModalidadPaseo = 'privado' | 'compartido'

/**
 * Representa un servicio de paseo de mascota.
 * Contiene información sobre quién solicita, quién pasea, duración, precio y localización.
 */
export interface Paseo extends BaseModel {
  /** ID del cuidador asignado al servicio (puede no estar asignado inicialmente). */
  id_cuidador?: string

  /**
   * Modalidad del paseo: 'privado' (solo mis mascotas) o 'compartido' (acepta otros tutores).
   * Define si el paseo permite que otros tutores unan sus mascotas.
   */
  modalidad?: ModalidadPaseo

  /** Cupo máximo de mascotas TOTALES para este paseo (incluyendo de todos los tutores). */
  cupo_maximo_mascotas?: number
  /** Contador actual de mascotas unidas a este paseo (subcolección). */
  mascotas_count?: number
  /** IDs de las mascotas participantes (para optimización de consultas). */
  mascota_ids?: string[]
  /** IDs de los tutores participantes (para paseos compartidos). */
  tutor_ids?: string[]
  /** Tipo de paseo (a demanda o programado). */
  tipo_paseo: TipoPaseo
  /** Fecha y hora de inicio del paseo. */
  fecha_hora_inicio: Date
  /** Duración estimada en minutos. */
  duracion_estimada: number
  /** Duración real */
  duracion_real?: number
  /** Costo del servicio en la moneda local. */
  precio: number
  /** Estado actual del paseo. */
  estado: PaseoStatus
  /** Fecha y hora real de inicio del paseo (cuando pasa a EN_PROGRESO). */
  fecha_inicio_real?: Date
  /** Fecha y hora real de fin del paseo (cuando pasa a FINALIZADO). */
  fecha_fin_real?: Date
  /** Ubicación de inicio (dirección o coordenadas). */
  ubicacion_inicio?: UbicacionSnapshot | string
  /** Texto legible de la ubicación de inicio (ej. "Casa", "Trabajo") para listas. */
  ubicacion_inicio_txt?: string
  /** Ubicación de término (dirección o coordenadas). */
  ubicacion_fin?: UbicacionSnapshot | string
  /** Texto legible de la ubicación de fin para listas. */
  ubicacion_fin_txt?: string
  /** Referencia al documento de tracking GPS si aplica. */
  tracking_gps?: string
  /** Nombre de la primera mascota para visualización en listas. */
  mascota_nombre_visual?: string
  /** Foto de la primera mascota para visualización en listas. */
  mascota_foto_visual?: string
  /** Lista de fotos (hasta 4) para paseos múltiples. */
  mascotas_fotos_visual?: string[]
  /** Nombre del cuidador para visualización en listas. */
  cuidador_nombre_visual?: string
  /** Foto del cuidador para visualización en listas. */
  cuidador_foto_visual?: string
  /** Tipo de solicitud: DIRECTA (a un cuidador) o ABIERTA (visible a varios cuidadores). */
  tipo_solicitud?: 'DIRECTA' | 'ABIERTA'
}

